/* Paratuberculose GDS 32-65 v1.2.16 — PWA multi-support */
const APP_VERSION='1.2.16';
const DB_NAME='ptb_gds_32_65';
const DB_VERSION=1;
const STORES=['herds','campaigns','nonnegatives','descendants','introductions','animals','analysisLots','analysisTreatments','meta'];
const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const digits=s=>String(s??'').replace(/\D/g,'');
const today=()=>new Date().toISOString().slice(0,10);
const fmtDate=v=>{if(!v)return''; const d=v instanceof Date?v:new Date(v); return isNaN(d)?String(v):d.toLocaleDateString('fr-FR')};
const num=v=>Number(String(v??'').replace(',','.'))||0;
const key=(...p)=>p.map(x=>String(x??'')).join('|');
function campaignFromDate(v){const d=v instanceof Date?v:new Date(v); if(isNaN(d))return''; const y=d.getFullYear(); return d.getMonth()>=6?`${y}/${y+1}`:`${y-1}/${y}`}
function currentCampaignDefault(){return '2025/2026'}
function toast(msg){const t=$('#toast');t.textContent=msg;t.hidden=false;clearTimeout(toast._t);toast._t=setTimeout(()=>t.hidden=true,3200)}
function download(name,content,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function csvEscape(v){const s=String(v??''); return /[;"\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function toCSV(rows,headers){return [headers.join(';'),...rows.map(r=>headers.map(h=>csvEscape(r[h])).join(';'))].join('\n')}

class IDBStore{
  constructor(){this.db=null}
  open(){return new Promise((res,rej)=>{const rq=indexedDB.open(DB_NAME,DB_VERSION);rq.onupgradeneeded=()=>{const db=rq.result;for(const s of STORES)if(!db.objectStoreNames.contains(s))db.createObjectStore(s,{keyPath:'id'})};rq.onsuccess=()=>{this.db=rq.result;res(this)};rq.onerror=()=>rej(rq.error)})}
  tx(store,mode='readonly'){return this.db.transaction(store,mode).objectStore(store)}
  all(store){return new Promise((res,rej)=>{const rq=this.tx(store).getAll();rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error)})}
  get(store,id){return new Promise((res,rej)=>{const rq=this.tx(store).get(id);rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error)})}
  put(store,obj){return new Promise((res,rej)=>{const rq=this.tx(store,'readwrite').put(obj);rq.onsuccess=()=>res(obj);rq.onerror=()=>rej(rq.error)})}
  bulkPut(store,arr){return new Promise((res,rej)=>{const tx=this.db.transaction(store,'readwrite'),os=tx.objectStore(store);arr.forEach(o=>os.put(o));tx.oncomplete=()=>res(arr.length);tx.onerror=()=>rej(tx.error)})}
  clear(store){return new Promise((res,rej)=>{const rq=this.tx(store,'readwrite').clear();rq.onsuccess=()=>res();rq.onerror=()=>rej(rq.error)})}
  delete(store,id){return new Promise((res,rej)=>{const rq=this.tx(store,'readwrite').delete(id);rq.onsuccess=()=>res();rq.onerror=()=>rej(rq.error)})}
}
const db=new IDBStore();
const state={view:'todo',campaign:'',herds:[],campaigns:[],nonnegatives:[],descendants:[],introductions:[],animals:[],analysisLots:[],analysisTreatments:[],meta:{},herdFilters:{q:'',dept:'',mode:''},auth:{accessToken:'',refreshToken:'',user:null,profile:null}};
function cloudConfigured(){return !!(state.meta.supabaseUrl&&state.meta.supabaseKey)}
function cloudLoggedIn(){return !!state.auth.accessToken}
function currentRole(){return state.auth.profile?.role||''}
function canWrite(){return !cloudLoggedIn()||['write','admin'].includes(currentRole())}
function isAdmin(){return cloudLoggedIn()&&currentRole()==='admin'}
function ensureWrite(){if(canWrite())return true;toast('Compte en lecture seule : modification interdite');return false}

async function loadState(){
  for(const s of ['herds','campaigns','nonnegatives','descendants','introductions','animals','analysisLots','analysisTreatments']) state[s]=await db.all(s);
  const meta=await db.all('meta'); state.meta=Object.fromEntries(meta.map(x=>[x.id,x.value]));
  state.campaign=state.meta.currentCampaign||currentCampaignDefault();
  if(!state.meta.currentCampaign)await setMeta('currentCampaign',state.campaign);
}
async function setMeta(id,value){state.meta[id]=value;await db.put('meta',{id,value})}

function getCampaignsList(){const set=new Set(state.campaigns.map(x=>x.campaign).filter(Boolean));set.add(state.campaign); return [...set].sort((a,b)=>b.localeCompare(a))}
function populateCampaignSelector(){const s=$('#globalCampaign');if(!s)return;s.innerHTML=getCampaignsList().map(c=>`<option ${c===state.campaign?'selected':''}>${esc(c)}</option>`).join('');}
function analysisAggregate(campaign=state.campaign){
  const map=new Map();
  for(const lot of state.analysisLots.filter(x=>x.campaign===campaign)){
    const k=String(lot.ede); if(!map.has(k))map.set(k,{ede:k,dept:lot.dept,campaign,lots:0,first:null,last:null,tested:0,positive:0,lastUpdate:null,dossiers:[]});
    const a=map.get(k);a.lots++; const d=lot.sampleDate?new Date(lot.sampleDate):null;if(d&&!isNaN(d)){if(!a.first||d<a.first)a.first=d;if(!a.last||d>a.last)a.last=d}
    a.tested+=num(lot.tested);a.positive+=num(lot.positive); const u=lot.lastUpdate?new Date(lot.lastUpdate):null;if(u&&!isNaN(u)&&(!a.lastUpdate||u>a.lastUpdate))a.lastUpdate=u;if(lot.labFile)a.dossiers.push(lot.labFile);
  }
  for(const a of map.values()){a.negative=Math.max(0,a.tested-a.positive);const t=state.analysisTreatments.find(x=>x.id===key(a.ede,campaign));const td=t?.treatmentDate?new Date(t.treatmentDate):null;const current=td&&a.lastUpdate&&td>=a.lastUpdate&&t.qualificationUpdated&&(a.positive===0||t.positivesManaged);a.status=current?'TRAITÉ':a.positive>0?'POSITIF À TRAITER':'À TRAITER';a.treatment=t||null}
  return map;
}
function animalIndex(){const m=new Map();for(const a of state.animals)m.set(String(a.animalId),a);return m}
function herdByEde(ede){return state.herds.find(h=>String(h.ede)===String(ede))}
function historyFor(ede){return state.campaigns.filter(c=>String(c.ede)===String(ede)).sort((a,b)=>String(b.campaign).localeCompare(String(a.campaign)))}
function activeAnimals(ede){return state.animals.filter(a=>String(a.ede)===String(ede))}

function render(){
  populateCampaignSelector();
  $$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
  try{
    const fn=views[state.view]||views.todo;
    $('#app').innerHTML=fn();
    bindView();
  }catch(e){
    console.error('Erreur affichage',state.view,e);
    $('#app').innerHTML=`<div class="error"><b>Erreur d’affichage :</b> ${esc(e.message||e)}<br><span class="help">La navigation reste disponible à gauche. Aucun enregistrement n’a été supprimé.</span></div>`;
  }
}
const pageHead=(title,sub='',actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const badgeMode=m=>m?`<span class="badge ${norm(m).includes('garantie')?'garantie':'ass'}">${esc(m)}</span>`:'';

function thresholdFor(tested){const n=num(tested);return n<=50?1:n<=200?2:3}
function nextCampaign(c=state.campaign){const m=String(c||'').match(/^(\d{4})\/(\d{4})$/);return m?`${Number(m[1])+1}/${Number(m[2])+1}`:''}
function protocolYearValue(c,h){const raw=String(c?.protocolYear||'').match(/\d+/);if(raw)return Number(raw[0]);const hist=historyFor(h?.ede||c?.ede).filter(x=>x.protocol&&norm(x.protocol).includes('1 bis')).sort((a,b)=>String(a.campaign).localeCompare(String(b.campaign)));const idx=hist.findIndex(x=>x.campaign===state.campaign);return idx>=0?idx+1:0}
function isFavorableA(h,c){const q=norm([h?.currentQualification,h?.qualificationAgds,c?.status,c?.situation].join(' '));return q.includes('favorable')&&(!q.includes('intermediaire'))||/\ba\b/.test(q)||norm(h?.mode).includes('garantie')&&q.includes('qual')}
function screeningFor1Bis(year){if(year<=0)return'Tous bovins ≥ 24 mois - sérologie individuelle';if(year<=3)return'Tous bovins ≥ 24 mois - sérologie individuelle';if(year===4||year===6||year===8)return'Tous bovins de 24 à 72 mois - sérologie individuelle';return'Pas de dépistage de maintien programmé par le schéma 1 bis cette campagne (à confirmer selon historique)'}
function protocolCode(protocol){
  const p=norm(protocol).replace(/référentiel|referentiel/g,'').trim();
  if(/(^|\s)3($|\s)/.test(p)||p.includes('③'))return'3';
  if((p.includes('2 bis')||p.includes('② bis')))return'2bis';
  if(/(^|\s)2($|\s)/.test(p)||p.includes('②'))return'2';
  if((p.includes('1 bis')||p.includes('① bis')))return'1bis';
  if(/(^|\s)1($|\s)/.test(p)||p.includes('①'))return'1';
  return p.includes('bis')?'1bis':'1bis';
}
function currentNonNegatives(ede){return state.nonnegatives.filter(n=>String(n.ede)===String(ede)&&(!n.campaign||n.campaign===state.campaign))}
function nnFacts(ede,t={}){
  const rows=currentNonNegatives(ede), labels=rows.map(n=>norm(n.result));
  const positives=rows.filter(n=>norm(n.result).includes('positif')).length;
  const doubts=rows.filter(n=>norm(n.result).includes('doute')).length;
  const infected=rows.filter(n=>norm(n.conclusion).includes('infect')).length;
  const suspect=rows.filter(n=>norm(n.conclusion).includes('suspect')).length;
  return{rows,positives,doubts,infected,suspect,doubtOnly:(doubts>0&&positives===0)||t.serologySituation==='doubt_only'};
}
function suspectedManagement(base){
  base.priority=2;base.label='Bovin suspect - suivi renforcé';base.caseRef='Bovins conclus suspects - gestion des bovins et du troupeau (p.6-7)';
  base.qualification='Statut du troupeau réattribué, bovin exclu du statut favorable';
  base.nextScreening='Bovin suspect : sérologie individuelle + PCR en N+1 s’il est encore présent. Si maintien A bisannuel : surveillance troupeau en N+1.';
  base.actions=['Exclure le bovin suspect du statut favorable.','Exclure son dernier descendant jusqu’à un résultat sérologique favorable obtenu après 24 mois.','Réforme avant N+1 fortement recommandée.','S’il reste présent en N+1 : sérologie individuelle + PCR ; si au moins un résultat positif, conclure infecté.'];
  return base;
}
function infectedHerdManagement(base,{maintenance,protocol,year,isolated,pcr,pcre}){
  const pc=protocolCode(protocol);
  base.priority=1;base.label='INFECTÉ - gestion prioritaire';
  const common=['Isoler et réformer le(s) bovin(s) conclu(s) infecté(s) avant le début de N+1.','Exclure la descendance des campagnes N et N-1 du statut favorable et la réformer dans les délais prévus.'];
  if(maintenance){
    if(isolated&&pcr==='negative'){
      base.caseRef='Cas n°1-① - maintien A, nombre ≤ seuil et PCR négative';
      base.qualification='Statut favorable réattribué après réforme du/des infecté(s)';
      base.nextScreening='N+1 : tous bovins ≥24 mois en sérologie individuelle. N+2 : 24-72 mois, puis retour à la surveillance bisannuelle si favorable.';
      base.actions=[...common,'Réattribuer le statut une fois les infectés réformés.'];
    }else if(!isolated&&pcr==='positive'){
      base.caseRef='Cas n°1-② - maintien A, nombre > seuil et ≥1 PCR positive';
      base.qualification='Retrait du statut favorable - plan de maîtrise proposé';
      base.nextScreening='Reprendre le processus de qualification au départ après réforme. Statut A/B seulement si infectés réformés avant le 1er dépistage et ≥24 mois avant le dernier dépistage qualifiant.';
      base.actions=['Réformer les bovins infectés.','Proposer un plan de maîtrise.'];
    }else{
      base.caseRef='Cas n°1-③ - maintien A, situation intermédiaire';
      base.qualification='Statut suspendu ; réattribution possible après contrôle N+1 favorable et réformes réalisées';
      base.nextScreening='N+1 : tous ≥24 mois. N+2 : tous ≥24 mois. N+3 : 24-72 mois, puis retour à la fréquence habituelle.';
      base.actions=[...common,'Ne pas vendre sous statut favorable les veaux de la génération en contact avant 2 contrôles favorables espacés ≥9 mois après 18 mois.'];
    }
    return base;
  }
  // Référentiels 1 / 1 bis
  if(pc==='1'||pc==='1bis'){
    if(year<=1){
      if(isolated&&pcr==='negative'){
        base.caseRef='Cas n°2a-① - acquisition référentiel ①/① bis, année 1';base.qualification='Poursuite normale de l’acquisition';base.nextScreening='N+1 : 2e série, tous bovins ≥24 mois.';base.actions=common;
      }else{
        base.caseRef='Cas n°2a-② - acquisition année 1 : > seuil ou ≥1 PCR positive';base.qualification='Plan de maîtrise + reprise du processus de qualification au départ';base.nextScreening='Redémarrer l’acquisition après réforme ; respecter le délai de 24 mois avant le dernier dépistage qualifiant.';base.actions=['Réformer les infectés.','Proposer un plan de maîtrise.'];
      }
      return base;
    }
    if(pc==='1'&&year===2){
      if(isolated&&pcr==='negative'&&pcre==='negative'){
        base.caseRef='Cas n°2b-① - référentiel ① année 2, ≤ seuil, PCR et PCRe négatives';base.qualification='Attribution du statut favorable (A) après réforme';base.nextScreening='N+1 : gestion de la descendance N/N-1 ; puis maintien selon le référentiel.';base.actions=common;
      }else if(!isolated||pcre==='positive_lt32'){
        base.caseRef='Cas n°2b-② - référentiel ① année 2, > seuil ou PCRe Ct <32';base.qualification='Plan de maîtrise + reprise du processus au départ';base.nextScreening='Reprendre l’acquisition après réforme et délais requis.';base.actions=['Réformer les infectés.','Proposer un plan de maîtrise.'];
      }else{
        base.caseRef='Cas n°2b-③ - référentiel ① année 2, situation intermédiaire';base.qualification='Acquisition prolongée sous conditions';base.nextScreening='N+1 : tous ≥24 mois ; si favorable et réformes réalisées, attribution A.';base.actions=[...common,'Situation intermédiaire : ≤ seuil avec ≥1 PCR positive ou PCRe Ct >32.'];
      }
      return base;
    }
    if(pc==='1bis'&&(year===2||year===3)){
      if(isolated&&pcr==='negative'){
        base.caseRef='Cas n°2c-① - référentiel ① bis année 2 ou 3';base.qualification=year===2?'Attribution du statut favorable intermédiaire (B)':'Attribution du statut favorable (A)';base.nextScreening=year===2?'N+1 : année 3, tous bovins ≥24 mois.':'N+1 : démarrage du protocole de maintien.';base.actions=common;
      }else if(!isolated){
        base.caseRef='Cas n°2c-② - référentiel ① bis, nombre > seuil';base.qualification='Plan de maîtrise + reprise du processus au départ';base.nextScreening='Reprendre l’acquisition après réforme et délais requis.';base.actions=['Réformer les infectés.','Proposer un plan de maîtrise.'];
      }else{
        base.caseRef='Cas n°2c-③ - référentiel ① bis, ≤ seuil et ≥1 PCR positive';base.qualification='Acquisition prolongée sous conditions';base.nextScreening=year===2?'N+1 : tous ≥24 mois ; si favorable B. N+2 : tous ≥24 mois ; si favorable A.':'N+1 : tous ≥24 mois ; si favorable A, puis maintien.';base.actions=[...common,'La situation intermédiaire ajoute un dépistage favorable au processus normal.'];
      }
      return base;
    }
  }
  // Référentiels 2 / 2 bis : Cas 3 renvoie aux règles du cas 2
  if(pc==='2'||pc==='2bis'){
    if(year<=1){base.caseRef='Cas n°3a → Cas n°2a - acquisition B, première phase';return infectedHerdManagement(base,{maintenance:false,protocol:'1 bis',year:1,isolated,pcr,pcre});}
    if(pc==='2'){base.caseRef='Cas n°3b → Cas n°2b - statut B, référentiel ②';const r=infectedHerdManagement(base,{maintenance:false,protocol:'1',year:2,isolated,pcr,pcre});r.caseRef='Cas n°3b (référentiel ②) → '+r.caseRef;return r;}
    const r=infectedHerdManagement(base,{maintenance:false,protocol:'1 bis',year:2,isolated,pcr,pcre});r.caseRef='Cas n°3b (référentiel ② bis) → '+r.caseRef;return r;
  }
  // Référentiel 3 : Cas 4 renvoie aux règles du cas 2
  if(pc==='3'){
    if(year<=1){const r=infectedHerdManagement(base,{maintenance:false,protocol:'1 bis',year:1,isolated,pcr,pcre});r.caseRef='Cas n°4a → '+r.caseRef;return r;}
    const r=infectedHerdManagement(base,{maintenance:false,protocol:'1',year:2,isolated,pcr,pcre});r.caseRef='Cas n°4b → '+r.caseRef;return r;
  }
  base.caseRef='Cas infecté non classé automatiquement';base.qualification='À valider avec le référentiel';base.nextScreening='À définir après validation du protocole et de l’ancienneté.';base.actions=['Vérifier le protocole et l’année de qualification.'];return base;
}
function movementProposal(base,t){
  base.priority=1;base.label='MOUVEMENT - gestion prioritaire';
  if(t.context==='intro_serology'){
    base.caseRef='Cas n°5 - résultat non séronégatif au moment de l’introduction';base.qualification='Statut/processus suspendu chez l’introducteur';base.nextScreening='Troupeau d’origine : gestion comme un non négatif de surveillance. Introducteur : départ du bovin ≤15 jours.';
    base.actions=['Informer le GDS du troupeau d’origine (et du naisseur si nécessaire).','Si seule une sérologie a été faite : PCR sous 15 jours.','Le bovin ne doit pas être conservé au-delà de 15 jours ; s’il est encore présent 2 mois après notification : perte du statut et reprise de l’acquisition.','Si PCR positive ou non réalisée sous 30 jours : visite d’évaluation du risque pour les 0-6 mois et les effluents.'];
  }else if(t.context==='intro_pcr'){
    base.caseRef='Cas n°6 - sérologie négative/inconnue et PCR positive à l’introduction';base.qualification='Gestion de l’introducteur comme Cas n°5';base.nextScreening='Origine : Ct <32 = Cas n°5 ; Ct >32 = évaluation portage passif / cas particulier.';
    base.actions=[t.pcrCt==='gt32'?'Ct >32 : évaluer le risque de portage passif (historique vendeur, situation introducteur, prophylaxies). Cas pouvant être soumis à la cellule nationale.':'Ct <32 ou non renseigné : gérer l’origine comme le Cas n°5.','Chez l’introducteur : appliquer la gestion du Cas n°5.'];
  }else{
    base.caseRef='Cas n°7 - résultat non négatif lors d’un contrôle postérieur à l’introduction';base.qualification='Statut/processus de l’acheteur suspendu';base.nextScreening='Acheteur : gérer comme un résultat non négatif de surveillance.';
    base.actions=['Troupeau d’origine : enquête épidémiologique et suites à l’appréciation du gestionnaire.','Prendre en compte la situation du troupeau introducteur.','Cas pouvant être soumis à la cellule nationale de gestion des cas particuliers.'];
  }
  return base;
}
function managementProposalAuto(ede,analysis=null){
  const h=herdByEde(ede)||{ede};const c=state.campaigns.find(x=>String(x.ede)===String(ede)&&x.campaign===state.campaign)||{};const a=analysis||analysisAggregate().get(String(ede));const t=a?.treatment||state.analysisTreatments.find(x=>x.id===key(String(ede),state.campaign))||{};const protocol=(c.protocol||h.protocol||'1 bis').trim();const year=protocolYearValue(c,h);const threshold=a?thresholdFor(a.tested):0;const maintenance=isFavorableA(h,c);const facts=nnFacts(ede,t);
  const base={priority:3,label:'En attente',caseRef:'Référentiel statut favorable v3 - novembre 2025',qualification:'À confirmer',nextScreening:screeningFor1Bis(year?year+1:1),actions:[],facts:[],note:'Proposition automatique à valider par le gestionnaire.'};
  if(t.context&&t.context.startsWith('intro_'))return movementProposal(base,t);
  if(t.context==='clinical'){
    base.priority=1;base.label='CLINIQUE ÉVOCATRICE - statut suspendu';base.caseRef='Clinique évocatrice de paratuberculose (p.3)';base.qualification='Suspension jusqu’à conclusion';base.nextScreening='Sérologie + PCR fèces sur l’animal. Selon résultats : recherche d’une autre cause ou dépistage de tous les ≥24 mois.';
    base.actions=['Réaliser sérologie et PCR sur fèces.','Si séronégatif + PCR négative et autre cause identifiée : lever la suspicion.','Si séronégatif + PCR négative sans autre cause : dépister tous les bovins ≥24 mois.','Dans tous les autres cas : bovin considéré infecté et dépistage complet ≥24 mois.'];return base;
  }
  if(!a){base.label='Résultats non reçus';base.actions=['Attendre / importer le résultat de la campagne.'];base.qualification=h.currentQualification||c.status||'Situation actuelle conservée';return base}
  if(a.positive===0&&!facts.doubtOnly){base.priority=3;base.label='Résultat favorable';base.caseRef='Référentiel statut favorable - surveillance des troupeaux';if(maintenance){base.qualification='Maintien du statut favorable (A), sous réserve du taux de réalisation et des autres exigences';base.nextScreening='Maintien : sérologie individuelle des 24-72 mois selon la fréquence applicable au troupeau.'}else if(protocolCode(protocol)==='1bis'){if(year===1){base.qualification='Poursuite de l’acquisition - 1er contrôle favorable';base.nextScreening='N+1 : tous bovins ≥24 mois, sérologie individuelle.'}else if(year===2){base.qualification='Proposition : statut favorable intermédiaire (B)';base.nextScreening='N+1 : tous bovins ≥24 mois, sérologie individuelle (année 3).'}else if(year>=3){base.qualification='Proposition : statut favorable (A)';base.nextScreening='N+1 : démarrage du maintien selon le schéma applicable.'}else base.qualification='Résultat favorable - vérifier l’ancienneté du protocole'}base.actions=['Vérifier le taux de réalisation du dépistage.','Valider la qualification proposée dans les deux logiciels.'];return base}
  base.priority=1;base.label='NON NÉGATIF - statut suspendu';base.caseRef='Gestion des résultats non négatifs v2 - novembre 2025';
  if(t.idcRecent){base.priority=2;base.label='IDC dans les 3 mois - résultat non conclusif';base.caseRef='Point d’attention IDC <3 mois (p.5)';base.qualification='Bovin suspect ; statut du troupeau suspendu';base.nextScreening='Recontrôle sérologique ≥3 mois après l’IDC.';base.actions=['Ne pas conclure infecté sur ce seul résultat.','Recontrôler ultérieurement ; si nouveau non négatif ≥3 mois après IDC, le résultat initial est confirmé.'];return base}
  const isolated=(t.infectedCount?num(t.infectedCount):Math.max(a.positive,facts.infected))<=threshold;const pcr=t.pcrOutcome||'';const pcre=t.pcreOutcome||'';
  if(facts.doubtOnly||t.serologySituation==='doubt_only'){
    base.caseRef='Résultats douteux sans positif (p.6)';base.priority=2;base.label='DOUTEUX SEUL(S) - recontrôle 15 à 30 jours';base.qualification='Statut suspendu en attente du recontrôle';base.nextScreening='Recontrôle sérologie + PCR des bovins douteux sous 15 à 30 jours.';
    const rs=t.repeatSerology||'';
    if(!rs||!pcr){base.actions=['Réaliser un nouveau prélèvement sanguin et une PCR fèces sous 15 à 30 jours.'];return base}
    if(rs==='negative'&&pcr==='negative'){base.label='Présumé non infecté';base.qualification='Statut réattribuable';base.caseRef='Douteux seul : recontrôle sérologie négative + PCR négative';base.actions=['Conclure le bovin présumé non infecté.'];return base}
    if(pcr==='positive')return infectedHerdManagement(base,{maintenance,protocol,year,isolated,pcr:'positive',pcre});
    if(rs==='doubtful'&&pcr==='negative')return suspectedManagement(base);
    if(rs==='positive'&&pcr==='negative'){
      if(!isolated)return infectedHerdManagement(base,{maintenance,protocol,year,isolated:false,pcr:'negative',pcre});
      if(!t.lrConclusion){base.caseRef='Douteux → PS2 positive / PCR négative : procédure LR possible';base.qualification='Suspension jusqu’à conclusion LR';base.nextScreening='Transmettre PS1 + PS2 au laboratoire de référence.';base.actions=['Les critères « isolés » sont remplis : appliquer la procédure LR.'];return base}
      if(t.lrConclusion==='presumed'){base.label='Présumé non infecté';base.qualification='Statut réattribuable';base.caseRef='Procédure LR - bovin présumé non infecté';base.actions=['Réattribuer le statut du troupeau.'];return base}
      if(t.lrConclusion==='suspect')return suspectedManagement(base);
      if(t.lrConclusion==='genetic'){base.priority=2;base.label='Discordance - analyses génétiques';base.caseRef='Annexe procédure LR - profil discordant';base.qualification='Statut à maintenir suspendu jusqu’à conclusion';base.actions=['Suivre les analyses génétiques / solliciter le laboratoire de référence.'];return base}
      if(t.lrConclusion==='infected')return infectedHerdManagement(base,{maintenance,protocol,year,isolated:true,pcr:'negative',pcre});
    }
  }
  if((a.positive>0||facts.positives>0)&&isolated){
    if(!pcr){base.caseRef='Positifs/douteux en nombre isolé (p.5)';base.qualification='Suspension en attente du recontrôle';base.nextScreening='Sous 15 à 30 jours : PS2 + PCR fèces.';base.actions=[`Nombre non négatif ≤ seuil (${threshold}).`,'Réaliser PS2 + PCR sous 15 à 30 jours.','Si ≥1 PCR positive : tous les bovins recontrôlés sont conclus infectés.','Si aucune PCR positive : envoyer PS1 + PS2 au laboratoire de référence.'];return base}
    if(pcr==='positive')return infectedHerdManagement(base,{maintenance,protocol,year,isolated:true,pcr:'positive',pcre});
    if(pcr==='negative'){
      if(!t.lrConclusion){base.caseRef='Procédure laboratoire de référence - conclusion attendue';base.qualification='Statut suspendu en attente de la conclusion LR';base.nextScreening='Envoyer PS1 + PS2 au LR ; appliquer ensuite le profil rendu.';base.actions=['Conclusion possible : présumé non infecté, suspect, infecté ou discordant nécessitant analyses génétiques.'];return base}
      if(t.lrConclusion==='presumed'){base.label='Présumé non infecté';base.qualification='Statut du troupeau réattribué';base.caseRef='Procédure LR - bovin présumé non infecté';base.actions=['Réattribuer le statut du troupeau.'];return base}
      if(t.lrConclusion==='suspect')return suspectedManagement(base);
      if(t.lrConclusion==='genetic'){base.priority=2;base.label='Discordance - analyses génétiques';base.caseRef='Annexe procédure LR - profil discordant';base.qualification='Statut à maintenir suspendu jusqu’à conclusion';base.actions=['Suivre les analyses génétiques / solliciter le laboratoire de référence.'];return base}
      if(t.lrConclusion==='infected')return infectedHerdManagement(base,{maintenance,protocol,year,isolated:true,pcr:'negative',pcre});
    }
  }
  // Autres situations : douteux/positif = infecté d’emblée ; PCR dans les 30 jours.
  if(!pcr){base.caseRef='Autres situations (p.6)';base.qualification='Bovin conclu infecté ; statut suspendu';base.nextScreening='PCR fèces dans les 30 jours après notification puis gestion selon Cas n°1 à 4.';base.actions=[`Nombre non négatif au-delà du seuil (${threshold}) ou situation ne permettant pas la procédure isolée.`,'Réaliser la PCR fèces sous 30 jours.'];return base}
  const inf=infectedHerdManagement(base,{maintenance,protocol,year,isolated,pcr,pcre});
  if(t.reformStatus==='not_reformed'){inf.priority=1;inf.actions.push('NON-RÉFORME : le troupeau reste suspendu ; retrait du statut si l’animal n’est pas réformé avant N+2.');inf.caseRef+=' + absence de réforme (p.11-12)'}
  if(t.descendantsReformed==='no'){inf.priority=1;inf.actions.push('DESCENDANCE NON RÉFORMÉE : si encore non réformée avant N+2, suspension du statut favorable.');inf.caseRef+=' + descendance N/N-1 non réformée'}
  return inf;
}

function isIntermediateCampaign(c,h=herdByEde(c?.ede)){
  if(!c)return false;if(c.intermediateYear)return true;
  if(num(c.tested)||num(c.positive)||num(c.doubtful))return false;
  const text=norm([c.screeningPlanned,c.situation,c.status,h?.screeningPlanned].join(' '));
  return norm(h?.mode||c.mode).includes('garantie')&&protocolCode(c.protocol||h?.protocol||'1 bis')==='1bis'&&(text.includes('intermediaire')||text.includes('maintien')||text.includes('favorable'));
}
function campaignScreeningLabel(c,h=herdByEde(c?.ede)){
  if(isIntermediateCampaign(c,h))return 'Année intermédiaire - aucun dépistage';
  return c?.screeningPlanned||c?.populationPlanned||c?.method||'';
}
function nextScreeningFromHistory(ede){
  const h=herdByEde(ede)||{},c=state.campaigns.find(x=>String(x.ede)===String(ede)&&x.campaign===state.campaign)||{};
  if(h.nextScreeningOverride)return h.nextScreeningOverride;
  if(c.nextScreeningOverride)return c.nextScreeningOverride;
  if(c.prophyNext)return c.prophyNext;
  if(isIntermediateCampaign(c,h))return 'Bovins 24-72 mois - sérologie individuelle';
  return screeningFor1Bis(protocolYearValue(c,h)?protocolYearValue(c,h)+1:1);
}
function managementProposal(ede,analysis=null){
  const p=managementProposalAuto(ede,analysis),h=herdByEde(ede)||{},c=state.campaigns.find(x=>String(x.ede)===String(ede)&&x.campaign===state.campaign)||{};
  const manual=h.nextScreeningOverride||c.nextScreeningOverride||c.prophyNext;
  if(manual)p.nextScreening=manual;else if(!analysisAggregate().get(String(ede))&&isIntermediateCampaign(c,h))p.nextScreening='Bovins 24-72 mois - sérologie individuelle';
  return p;
}
function historyEventHTML(c){
  const h=herdByEde(c.ede),inter=isIntermediateCampaign(c,h),screen=inter?'Année intermédiaire - aucun dépistage':campaignScreeningLabel(c,h);
  const counts=inter?'Aucun prélèvement prévu':(num(c.tested)?`${num(c.tested)} dépistés · ${num(c.positive)} positifs${num(c.doubtful)?` · ${num(c.doubtful)} douteux`:''}`:'');
  const lots=Array.isArray(c.sampleDetails)&&c.sampleDetails.length>1?`<small>${c.sampleDetails.map(x=>`${fmtDate(x.date)} : ${num(x.tested)}`).join(' + ')} = <b>${num(c.tested)}</b></small>`:'';
  return `<div class="event"><div class="event-title"><strong>${esc(c.campaign)}</strong><button class="mini-btn edit-campaign" data-campaign-id="${esc(c.id)}">Modifier</button></div><small>${esc(c.status||c.situation||(inter?'Année intermédiaire':''))}</small><p>${esc(screen)}</p><small>${esc(counts)}</small>${lots}</div>`;
}

function decisionHTML(p){const cls=p.priority===1?'high':p.priority===2?'medium':p.label.toLowerCase().includes('favorable')||p.label.toLowerCase().includes('présumé')?'good':'';return`<div class="decision ${cls}"><h3><span class="smart-tag">Référentiel intelligent</span> ${esc(p.label)}</h3><div><b>Qualification / statut proposé :</b> ${esc(p.qualification)}</div><div><b>Suite / N+1 proposée :</b> ${esc(p.nextScreening)}</div>${p.actions?.length?`<ul>${p.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<small><b>Cas :</b> ${esc(p.caseRef)}. ${esc(p.note||'')} <a class="ref-link" target="_blank" href="./referentiel/Gestion_resultats_non_negatifs_v2_nov2025.pdf">Gestion non négatifs</a> · <a class="ref-link" target="_blank" href="./referentiel/Referentiel_statut_favorable_v3_nov2025.pdf">Statut favorable</a></small></div>`}
function priorityScore(a){if(a.status==='TRAITÉ')return 99;if(a.positive>0)return 0;return 1}
function priorityList(){const rows=[...analysisAggregate().values()].sort((a,b)=>priorityScore(a)-priorityScore(b)||String(a.lastUpdate).localeCompare(String(b.lastUpdate)));if(!rows.length)return'<div class="empty">Aucun résultat importé pour cette campagne.</div>';return`<div class="priority-list">${rows.map(a=>{const p=managementProposal(a.ede,a);const cls=a.status==='TRAITÉ'?'done':a.positive>0?'':'p2';return`<div class="priority-item ${cls}"><div class="priority-bar"></div><div class="priority-body"><div class="priority-title"><span>${esc(herdByEde(a.ede)?.name||a.ede)}</span><span class="badge ${a.positive>0?'red':'yellow'}">${a.positive>0?`${a.positive} positif(s)`:'Résultat à valider'}</span></div><div class="priority-meta">EDE ${esc(a.ede)} · ${a.tested} dépistés · ${a.negative} négatifs · ${fmtDate(a.last)} · ${esc(p.caseRef)}</div><div class="mini">${esc(p.qualification)} · N+1 : ${esc(p.nextScreening)}</div></div><div class="priority-action"><button class="primary" data-herd="${esc(a.ede)}">Ouvrir</button></div></div>`}).join('')}</div>`}
function campaignStatus(c,a){if(a){if(a.status==='TRAITÉ')return'<span class="status-dot received"></span>Traité';if(a.positive>0)return'<span class="status-dot positive"></span>Positif à traiter';return'<span class="status-dot todo"></span>Reçu - à valider'}if(isIntermediateCampaign(c))return'<span class="status-dot received"></span>Année intermédiaire - pas de dépistage';if(num(c?.tested)>0)return'<span class="status-dot received"></span>Résultat historique enregistré';return'<span class="status-dot"></span>Résultat non reçu'}
function kpi(label,value,sub=''){return`<div class="kpi"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="sub">${esc(sub)}</div></div>`}
function pie(value,total,c1='#8e2c6d',c2='#e7eaec'){const pct=total?Math.max(0,Math.min(100,value/total*100)):0;return`<div class="pie" style="background:conic-gradient(${c1} 0 ${pct}%,${c2} ${pct}% 100%)"></div>`}

function nonNegFollowupLabel(n){
  if(n.followupStatus)return n.followupStatus;
  if(n.conclusion)return `LR / conclusion : ${n.conclusion}`;
  if(n.repeatSerology||n.pcrResult)return 'Recontrôle effectué';
  return 'Non renseigné';
}
function nonNegTableForHerd(rows){const ai=animalIndex();if(!rows.length)return'<div class="empty">Aucun non négatif enregistré.</div>';return`<div class="table-wrap"><table><thead><tr><th>Campagne</th><th>Animal</th><th>Nom / travail</th><th>Résultat</th><th>Date</th><th>Recontrôle / LR</th><th>PS2</th><th>PCR</th><th>Conclusion</th><th>Réforme</th><th>Présence</th><th>Sortie</th><th></th></tr></thead><tbody>${rows.map(n=>{const a=ai.get(String(n.animalId));return`<tr class="click-row nn-edit" data-nn-id="${esc(n.id)}"><td>${esc(n.campaign||'')}</td><td><strong>${esc(n.animalId)}</strong></td><td>${esc(a?.name||n.name||'')} ${a?.workNo?`(${esc(a.workNo)})`:''}</td><td>${esc(n.result||'')}</td><td>${fmtDate(n.date)}</td><td><strong>${esc(nonNegFollowupLabel(n))}</strong></td><td>${esc(n.repeatSerology||'')}</td><td>${esc(n.pcrResult||'')}</td><td>${esc(n.conclusion||'')}</td><td>${esc(n.reformStatus||'')}</td><td>${esc(n.presence||a?.presence||'')}</td><td>${fmtDate(n.exitDate||a?.exitDate)}</td><td><button class="mini-btn nn-edit" data-nn-id="${esc(n.id)}">Modifier</button></td></tr>`}).join('')}</tbody></table></div>`}

function statusBadge(s){return`<span class="badge ${s==='POSITIF À TRAITER'?'red':s==='À TRAITER'?'yellow':'green'}">${esc(s||'')}</span>`}
function analysisTable(rows){if(!rows.length)return'<div class="empty">Aucune analyse pour cette campagne.</div>';return`<div class="table-wrap"><table><thead><tr><th>EDE</th><th>Éleveur</th><th>Lots</th><th>Prélèvement</th><th>Dépistés</th><th>Négatifs</th><th>Positifs</th><th>Dernière MAJ</th><th>Statut</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.ede)}</td><td class="click-row" data-herd="${esc(a.ede)}">${esc(herdByEde(a.ede)?.name||'')}</td><td>${a.lots||0}</td><td>${fmtDate(a.last)}</td><td>${a.tested||0}</td><td>${a.negative||0}</td><td><strong>${a.positive||0}</strong></td><td>${fmtDate(a.lastUpdate)}</td><td>${statusBadge(a.status||'')}</td><td><button class="ghost analysis-treat" data-ede="${esc(a.ede)}">Traiter</button></td></tr>`).join('')}</tbody></table></div>`}

function filteredHerds(){const f=state.herdFilters;return state.herds.filter(h=>{const hay=norm([h.ede,h.name,h.commune,h.vet,h.mode,h.currentQualification].join(' '));return(!f.q||hay.includes(norm(f.q)))&&(!f.dept||String(h.dept)===f.dept)&&(!f.mode||norm(h.mode).includes(norm(f.mode)))})}
function herdTable(rows){if(!rows.length)return'<div class="empty">Aucun cheptel.</div>';return`<div class="table-wrap"><table><thead><tr><th>Dépt</th><th>EDE</th><th>Éleveur</th><th>Commune</th><th>Mode</th><th>Qualification actuelle</th><th>Vétérinaire</th></tr></thead><tbody>${rows.map(h=>`<tr class="click-row" data-herd="${esc(h.ede)}"><td>${esc(h.dept)}</td><td><strong>${esc(h.ede)}</strong></td><td>${esc(h.name)}</td><td>${esc(h.commune||'')}</td><td>${badgeMode(h.mode)}</td><td>${esc(h.currentQualification||h.qualification||'')}</td><td>${esc(h.vet||'')}</td></tr>`).join('')}</tbody></table></div>`}

const views={
 todo(){const ag=[...analysisAggregate().values()],pos=ag.filter(x=>x.positive>0).length,todo=ag.filter(x=>x.status!=='TRAITÉ').length;return pageHead('À traiter',`Priorités - campagne ${esc(state.campaign)}`,`<button class="primary" data-go="imports">Importer des résultats</button>`)+`<div class="grid kpi-grid">${kpi('Résultats reçus',ag.length,`${state.herds.length} engagés`)}${kpi('À traiter',todo,'dossiers ouverts')}${kpi('Cheptels positifs',pos,'priorité haute')}${kpi('Traités',ag.filter(x=>x.status==='TRAITÉ').length,'validés')}</div><div class="card"><h2>File de traitement</h2><p class="help">Les positifs sont placés en tête. La proposition de gestion s’appuie sur les référentiels novembre 2025 et doit être validée avant application.</p>${priorityList()}</div>`},
 campaigns(){const rows=state.campaigns.filter(c=>c.campaign===state.campaign),ag=analysisAggregate();const merged=rows.map(c=>({...c,analysis:ag.get(String(c.ede))}));return pageHead('Campagne',`Suivi de tous les engagés - ${esc(state.campaign)}`,`<button class="primary" data-go="imports">Importer</button>`)+`<div class="toolbar"><input id="campaignQ" type="search" placeholder="EDE, éleveur, mode, statut…"><select id="campaignResult"><option value="">Tous</option><option value="missing">Résultat non reçu</option><option value="received">Résultat reçu</option><option value="positive">Positif</option><option value="todo">À traiter</option></select></div><div id="campaignTable">${campaignTableHTML(merged)}</div>`},
 herds(){const f=state.herdFilters,rows=filteredHerds();return pageHead('Éleveurs',`<span id="herdCount">${rows.length}</span> cheptel(s)`,``)+`<div class="toolbar"><input id="herdQ" type="search" inputmode="numeric" autocomplete="off" placeholder="EDE complet, nom, commune, vétérinaire…" value="${esc(f.q)}"><select id="herdDept"><option value="">32 + 65</option><option ${f.dept==='32'?'selected':''}>32</option><option ${f.dept==='65'?'selected':''}>65</option></select><select id="herdMode"><option value="">Garantie + Assainissement</option><option ${f.mode==='Garantie'?'selected':''}>Garantie</option><option ${f.mode==='Assainissement'?'selected':''}>Assainissement</option></select></div><div id="herdTable">${herdTable(rows)}</div>`},
 herdDetail(){return herdDetailHTML(state.selectedHerd)},
 imports(){const hc=state.meta.historyCounts||{};return pageHead('Imports','Les fichiers bruts sont reconnus directement',`<button class="primary" id="btnImportBundled">Restaurer l’historique initial complet</button>`)+`<div class="card"><h3>Historique intégré à l’application</h3><p class="help">Aucun fichier Excel à sélectionner : la base historique est déjà embarquée. ${hc.herds||193} éleveurs · ${hc.campaigns||1959} campagnes · ${hc.nonnegatives||2165} non négatifs · ${hc.descendants||1004} descendants · ${hc.introductions||1414} introductions.</p><p><b>Données actuellement chargées :</b> ${state.herds.length} éleveurs · ${state.campaigns.length} campagnes · ${state.animals.length} bovins.</p><p class="help">Si ces compteurs sont à 0, cliquer une fois sur « Restaurer l’historique initial complet ».</p></div><div class="grid split"><div>${importCard('animals32','Animaux 32','Export bovins brut du 32. Met à jour présence, sorties, mères et descendants.','.csv')}${importCard('animals65','Animaux 65','Export bovins brut du 65.','.csv')}</div><div>${importCard('analysis32','Analyses 32','Export analyses exploitation détaillé du 32. Agrégation automatique des lots par EDE/campagne.','.csv')}${importCard('analysis65','Analyses 65','Export analyses exploitation détaillé du 65.','.csv')}<div class="card"><h3>Après import</h3><p class="help">La file « À traiter » est reconstruite automatiquement. Les numéros individuels des non négatifs restent saisis dans la fiche éleveur, car l’export d’analyses exploitation ne les contient pas.</p></div></div></div>`},
 exports(){return pageHead('Exports','Listes d’engagés et de bovins')+`<div class="grid split"><div class="card"><h2>Engagés</h2><div class="actions"><button class="primary export-btn" data-export="engages">Tous les engagés</button><button class="ghost export-btn" data-export="garantie">Garantie</button><button class="ghost export-btn" data-export="ass">Assainissement</button><button class="ghost export-btn" data-export="garantie32">Garantie 32</button><button class="ghost export-btn" data-export="garantie65">Garantie 65</button><button class="ghost export-btn" data-export="ass32">Assainissement 32</button><button class="ghost export-btn" data-export="ass65">Assainissement 65</button></div></div><div class="card"><h2>Bovins</h2><div class="actions"><button class="primary export-btn" data-export="animalsPresent">Bovins présents des engagés</button><button class="ghost export-btn" data-export="animalsAll">Tous bovins chargés</button><button class="ghost export-btn" data-export="nonnegpresent">Non négatifs présents</button><button class="ghost export-btn" data-export="descendants">Descendants</button></div></div></div><div class="card"><h2>Suivi campagne</h2><div class="actions"><button class="ghost export-btn" data-export="positifs">Cheptels positifs</button><button class="ghost export-btn" data-export="campaignFollowup">Suivi de tous les engagés</button><button class="ghost export-btn" data-export="introductions">Introductions</button></div></div><div class="card"><h2>Sauvegarde complète Excel</h2><p class="help">Recrée un classeur complet avec les éleveurs, toutes les campagnes, non négatifs, descendants, introductions, animaux, analyses et décisions de traitement. Ce fichier peut servir d’archive ou de base de reprise.</p><button class="primary" id="exportFullExcel">Exporter toute la base en Excel</button></div>`},
 balance(){const b=campaignBounds();return pageHead('Bilan & récap',`Campagne ${esc(state.campaign)} · ${esc(b.label)}`,`<button class="primary export-btn" data-export="bilan">Exporter le bilan CSV</button>`)+`<div class="card period-banner"><strong>Période de référence :</strong> ${esc(b.label)}. Tous les indicateurs, compteurs et graphiques ci-dessous sont bornés sur cette période.</div>`+deptBalanceHTML(32)+deptBalanceHTML(65)+`<div class="card"><h2>Référentiels intégrés</h2><p class="help">Les indicateurs utilisent les résultats importés et, à défaut, les résultats historiques enregistrés pour la campagne active. La période d’une campagne va toujours du 1er juillet au 30 juin.</p></div>`},
 settings(){const prof=state.auth.profile,logged=cloudLoggedIn();return pageHead('Paramètres','Campagne active, sauvegardes et synchronisation')+`<div class="card"><h2>Campagne active</h2><div class="form-grid"><div class="field"><label>Campagne</label><input id="settingCampaign" value="${esc(state.campaign)}" placeholder="2025/2026"></div><div class="field"><label>&nbsp;</label><button class="primary" id="saveCampaign">Enregistrer</button></div></div></div><div class="card"><h2>Cloud Supabase / multi-support</h2><p class="help">Une fois Supabase configuré, les mêmes données peuvent être récupérées sur PC, téléphone ou tablette. Les comptes utilisent Supabase Auth et un rôle Lecture, Écriture ou Admin.</p><div class="form-grid"><div class="field"><label>URL Supabase</label><input id="sbUrl" value="${esc(state.meta.supabaseUrl||'')}"></div><div class="field"><label>Clé publique / anon</label><input id="sbKey" type="password" value="${esc(state.meta.supabaseKey||'')}"></div></div><div class="actions" style="margin-top:12px"><button class="primary" id="saveSupabase">Enregistrer</button></div>${logged?`<div class="cloud-user"><b>Connecté :</b> ${esc(state.auth.user?.email||'')} · rôle <strong>${esc(prof?.role||'lecture')}</strong></div><div class="actions"><button class="primary" id="pullSupabase">Récupérer la base cloud</button>${canWrite()?'<button class="ghost" id="pushSupabase">Envoyer la base locale</button>':''}<button class="ghost" id="logoutSupabase">Se déconnecter</button></div>${isAdmin()?'<div id="userAdminPanel" class="user-admin"><h3>Droits utilisateurs</h3><p class="help">Les comptes doivent d’abord exister dans Supabase Auth. Ici, tu peux changer leur rôle.</p><div id="cloudUsers">Chargement…</div></div>':''}`:`<div class="form-grid auth-box"><div class="field"><label>E-mail</label><input id="sbEmail" type="email"></div><div class="field"><label>Mot de passe</label><input id="sbPassword" type="password"></div></div><div class="actions"><button class="primary" id="loginSupabase">Se connecter</button></div>`}</div><div class="card"><h2>Sauvegarde / restauration</h2><div class="actions"><button class="ghost" id="restoreJsonBtn">Restaurer JSON</button><input id="restoreJsonInput" type="file" accept=".json" hidden><button class="danger" id="resetDbBtn">Réinitialiser les données locales</button></div></div>`}
};
function campaignTableHTML(rows){if(!rows.length)return'<div class="empty">Aucun engagé pour cette campagne.</div>';return`<div class="table-wrap"><table><thead><tr><th>EDE</th><th>Éleveur</th><th>Mode</th><th>Dépistage prévu</th><th>Résultat</th><th>Dépistés</th><th>+ / -</th><th>Qualification proposée</th><th>N+1 proposé</th></tr></thead><tbody>${rows.map(c=>{const h=herdByEde(c.ede),a=c.analysis,p=managementProposal(c.ede,a),histTest=num(c.tested);const cls=a?.positive?'positive':a?.status==='TRAITÉ'?'treated':'waiting';return`<tr class="click-row campaign-row ${cls}" data-herd="${esc(c.ede)}"><td><strong>${esc(c.ede)}</strong></td><td>${esc(h?.name||c.name||'')}</td><td>${badgeMode(h?.mode||c.mode)}</td><td>${esc(campaignScreeningLabel(c,h)||'')}</td><td>${campaignStatus(c,a)}</td><td>${a?a.tested:(histTest||'')}</td><td>${a?`${a.positive} / ${a.negative}`:(histTest?`${num(c.positive)} / ${num(c.negative)}`:'')}</td><td>${esc(p.qualification)}</td><td>${esc(p.nextScreening)}</td></tr>`}).join('')}</tbody></table></div>`}
function herdDetailHTML(ede){if(!ede)return pageHead('Éleveur','Aucun dossier sélectionné');const h=herdByEde(ede)||{ede};const hist=historyFor(ede),animals=activeAnimals(ede),nn=state.nonnegatives.filter(x=>String(x.ede)===String(ede)),desc=state.descendants.filter(x=>String(x.ede)===String(ede)),intro=state.introductions.filter(x=>String(x.ede)===String(ede)),a=analysisAggregate().get(String(ede)),p=managementProposal(ede,a),isGuarantee=norm(h.mode).includes('garantie');return`<button class="ghost back-btn" id="backToHerds">← Retour</button><div class="herd-head"><div>${pageHead(h.name||'Éleveur',`EDE ${esc(ede)} · département ${esc(h.dept||'')}`)}</div><div class="stat-line">${badgeMode(h.mode)}<span class="stat-pill">${esc(h.currentQualification||'Qualification non renseignée')}</span></div></div><div class="section-nav"><a href="#situation">Situation</a><a href="#analyses">Analyses</a><a href="#nonneg">Non négatifs (${nn.length})</a><a href="#desc">Descendants (${desc.length})</a>${isGuarantee?`<a href="#intro">Introductions (${intro.length})</a>`:''}<a href="#history">Historique</a></div><section id="situation" class="herd-section card"><div class="page-head"><div><h2>Situation actuelle</h2></div><button class="ghost" id="btnEditHerd">Modifier la fiche</button></div><div class="form-grid"><div><b>Vétérinaire</b><br>${esc(h.vet||'')}</div><div><b>Protocole</b><br>${esc(h.protocol||'1 bis')}</div><div><b>Qualification AGDS</b><br>${esc(h.qualificationAgds||h.currentQualification||'')}</div><div><b>Qualification nationale</b><br>${esc(h.qualificationNational||'')}</div><div><b>Dépistage N+1 retenu</b><br>${esc(nextScreeningFromHistory(ede))}</div><div class="field full"><b>Commentaire</b><br>${esc(h.comment||h.currentSituation||'')}</div></div>${Number(h.dept)===32?`<div class="reimbursement-box"><h3>Remboursement analyses - Gers (32)</h3><div class="form-grid"><div><b>Facture reçue</b><br>${esc(h.invoiceReceived||'Non')}</div><div><b>Date réception</b><br>${fmtDate(h.invoiceReceivedDate)}</div><div><b>Année de remboursement</b><br>${esc(h.reimbursementYear||'Non renseignée')} / 4</div><div><b>Date réponse compta</b><br>${fmtDate(h.accountingReplyDate)}</div></div></div>`:''}<div class="actions" style="margin:12px 0"><button class="primary" id="btnHerdAssistant">Ouvrir l’assistant référentiel</button></div>${decisionHTML(p)}</section><section id="analyses" class="herd-section card"><h2>Analyses - ${esc(state.campaign)}</h2>${a?analysisTable([a]):'<div class="empty">Aucun résultat importé pour cette campagne.</div>'}</section><div class="herd-management-grid"><section id="nonneg" class="herd-section card management-panel"><div class="page-head"><div><h2>Non négatifs</h2><p>${nn.length} animal(aux) enregistré(s)</p></div><button class="primary" id="btnAddNNForHerd">+ Ajouter</button></div>${nonNegTableForHerd(nn)}</section><section id="desc" class="herd-section card management-panel"><div class="page-head"><div><h2>Descendants</h2><p>${desc.length} descendant(s)</p></div><button class="primary" id="btnAddDescForHerd">+ Ajouter</button></div>${descendantTable(desc)}</section>${isGuarantee?`<section id="intro" class="herd-section card management-panel"><div class="page-head"><div><h2>Introductions</h2><p>Suivi spécifique Garantie · ${intro.length} introduction(s)</p></div><button class="primary" id="btnAddIntroForHerd">+ Ajouter</button></div>${introductionTable(intro)}</section>`:''}</div><section id="history" class="herd-section card"><h2>Historique campagnes</h2><p class="help">Les prophylaxies réalisées en plusieurs fois sont additionnées dans la campagne. Une année sans prélèvement prévue par le protocole est affichée comme année intermédiaire.</p><div class="timeline">${hist.map(historyEventHTML).join('')||'<div class="empty">Pas d’historique.</div>'}</div></section>`}
