function openDescForm(defaultEde='',editId=''){if(!ensureWrite())return;const old=editId?state.descendants.find(x=>String(x.id)===String(editId)):null,d=old||{ede:defaultEde};openModal(`<h2>${old?'Modifier':'Ajouter'} un descendant</h2><div class="form-grid"><div class="field"><label>EDE</label><input id="dEde" value="${esc(d.ede||defaultEde)}"></div><div class="field"><label>N° mère</label><input id="dMother" value="${esc(d.motherId||'')}"></div><div class="field"><label>N° descendant</label><input id="dAnimal" value="${esc(d.animalId||'')}"></div><div class="field"><label>Date naissance</label><input id="dBirth" type="date" value="${esc(String(d.birthDate||'').slice(0,10))}"></div><div class="field"><label>Présence</label><select id="dPresence"><option value=""></option><option ${d.presence==='Présent'?'selected':''}>Présent</option><option ${d.presence==='Sorti'?'selected':''}>Sorti</option></select></div><div class="field"><label>Date sortie</label><input id="dExit" type="date" value="${esc(String(d.exitDate||'').slice(0,10))}"></div><div class="field"><label>Cause sortie</label><select id="dCause"><option value=""></option>${['Élevage','Boucherie','Mort','Héritage','Autoconsommation'].map(x=>`<option ${d.exitCause===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Résultat / contrôle</label><input id="dResult" value="${esc(d.result||d.control||'')}"></div><div class="field full"><label>Commentaire</label><textarea id="dComment">${esc(d.comment||'')}</textarea></div></div><div class="actions"><button class="primary" id="saveDesc">Enregistrer</button>${old?'<button class="danger" id="deleteDesc">Supprimer</button>':''}</div>`);$('#saveDesc').onclick=async()=>{const ede=$('#dEde').value.trim(),animalId=digits($('#dAnimal').value);if(!ede||!animalId)return toast('EDE et descendant obligatoires');const obj={...d,id:old?.id||key(ede,animalId,Date.now()),ede,motherId:digits($('#dMother').value),animalId,birthDate:$('#dBirth').value,presence:$('#dPresence').value,exitDate:$('#dExit').value,exitCause:$('#dCause').value,result:$('#dResult').value.trim(),comment:$('#dComment').value.trim()};await db.put('descendants',obj);state.descendants=await db.all('descendants');closeModal();render();toast('Descendant enregistré')};if(old&&$('#deleteDesc'))$('#deleteDesc').onclick=async()=>{if(!confirm('Supprimer ce descendant ?'))return;await db.delete('descendants',old.id);state.descendants=await db.all('descendants');closeModal();render()}}
function openIntroForm(defaultEde='',editId=''){if(!ensureWrite())return;const h=herdByEde(defaultEde);if(h&&!norm(h.mode).includes('garantie'))return toast('Les introductions sont suivies uniquement pour les cheptels Garantie');const old=editId?state.introductions.find(x=>String(x.id)===String(editId)):null,i=old||{ede:defaultEde,campaign:state.campaign};openModal(`<h2>${old?'Modifier':'Ajouter'} une introduction</h2><div class="form-grid"><div class="field"><label>EDE</label><input id="iEde" value="${esc(i.ede||defaultEde)}"></div><div class="field"><label>Campagne</label><input id="iCamp" value="${esc(i.campaign||state.campaign)}"></div><div class="field"><label>N° bovin</label><input id="iAnimal" value="${esc(i.animalId||'')}"></div><div class="field"><label>Date introduction</label><input id="iDate" type="date" value="${esc(String(i.entryDate||i.introductionDate||'').slice(0,10))}"></div><div class="field"><label>Date naissance</label><input id="iBirth" type="date" value="${esc(String(i.birthDate||'').slice(0,10))}"></div><div class="field"><label>PCR introduction</label><input id="iPcr" value="${esc(i.pcr||i.pcrResult||'')}"></div><div class="field"><label>Sérologie introduction</label><input id="iSero" value="${esc(i.serology||i.serologyResult||'')}"></div><div class="field"><label>Résultat / contrôle</label><input id="iResult" value="${esc(i.result||i.control||'')}"></div><div class="field full"><label>Commentaire</label><textarea id="iComment">${esc(i.comment||'')}</textarea></div></div><div class="actions"><button class="primary" id="saveIntro">Enregistrer</button>${old?'<button class="danger" id="deleteIntro">Supprimer</button>':''}</div>`);$('#saveIntro').onclick=async()=>{const ede=$('#iEde').value.trim(),animalId=digits($('#iAnimal').value);if(!ede||!animalId)return toast('EDE et bovin obligatoires');const hh=herdByEde(ede);if(hh&&!norm(hh.mode).includes('garantie'))return toast('Introduction refusée : le cheptel n’est pas en Garantie');const obj={...i,id:old?.id||key($('#iCamp').value,ede,animalId,$('#iDate').value||Date.now()),ede,campaign:$('#iCamp').value,animalId,entryDate:$('#iDate').value,birthDate:$('#iBirth').value,pcr:$('#iPcr').value.trim(),serology:$('#iSero').value.trim(),result:$('#iResult').value.trim(),comment:$('#iComment').value.trim()};await db.put('introductions',obj);state.introductions=await db.all('introductions');closeModal();render();toast('Introduction enregistrée')};if(old&&$('#deleteIntro'))$('#deleteIntro').onclick=async()=>{if(!confirm('Supprimer cette introduction ?'))return;await db.delete('introductions',old.id);state.introductions=await db.all('introductions');closeModal();render()}}
function openAnimalsModal(ede){const rows=activeAnimals(ede);openModal(`<h2>Animaux du cheptel ${esc(ede)}</h2><p class="help">Données issues du dernier import animaux. Elles servent automatiquement à la présence, aux sorties et aux liens mère-descendant.</p>${animalTable(rows.slice(0,1000))}`)}
function exportFullExcel(){if(!window.XLSX)return toast('Bibliothèque Excel indisponible. Ouvrir l’application avec internet puis réessayer.');const wb=XLSX.utils.book_new(),add=(name,rows)=>{const cleaned=(rows||[]).map(r=>{const o={};for(const [k,v] of Object.entries(r||{})){if(k==='raw')continue;o[k]=v instanceof Date?v.toISOString():v}return o});const ws=XLSX.utils.json_to_sheet(cleaned.length?cleaned:[{Info:'Aucune donnée'}]);XLSX.utils.book_append_sheet(wb,ws,name.slice(0,31))};add('CHEPTELS',state.herds);add('CAMPAGNES',state.campaigns);add('NON_NEGATIFS',state.nonnegatives);add('DESCENDANTS',state.descendants);add('INTRODUCTIONS',state.introductions);add('ANIMAUX',state.animals);add('ANALYSES_LOTS',state.analysisLots);add('TRAITEMENTS',state.analysisTreatments);add('PARAMETRES',[{Campagne_active:state.campaign,Version:APP_VERSION,Date_export:new Date().toISOString()}]);XLSX.writeFile(wb,`Sauvegarde_Paratuberculose_GDS_32_65_${today()}.xlsx`);toast('Sauvegarde Excel créée')}


async function restoreBundledHistory(opts={}){
  const silent=!!opts.silent, force=!!opts.force;
  try{
    if(!silent&&force&&!confirm('Restaurer l’historique initial complet ? Les données historiques locales seront remplacées par la base fournie avec l’application.'))return;
    if(!silent)toast('Restauration de l’historique initial…');
    let seed=window.PTB_BUNDLED_HISTORY||null;
    if(!seed){
      const r=await fetch('./migration/history_seed.json',{cache:'no-store'});
      if(!r.ok)throw new Error('Base historique intégrée introuvable');
      seed=await r.json();
    }
    if(!seed||!Array.isArray(seed.herds)||!Array.isArray(seed.campaigns))throw new Error('Base historique intégrée invalide');
    for(const store of ['herds','campaigns','nonnegatives','descendants','introductions']){
      await db.clear(store);
      const arr=Array.isArray(seed[store])?seed[store]:[];
      if(arr.length)await db.bulkPut(store,arr);
    }
    // Les résultats de campagne et traitements ne font pas partie de l’historique initial.
    await db.clear('analysisLots'); await db.clear('analysisTreatments');
    await db.clear('animals'); if(Array.isArray(seed.animals)&&seed.animals.length)await db.bulkPut('animals',seed.animals)
    await setMeta('currentCampaign','2025/2026');
    await setMeta('campaignUserSet',false);
    await setMeta('bundledHistoryLoaded','1.2.4');
    await setMeta('historyCounts',{herds:(seed.herds||[]).length,campaigns:(seed.campaigns||[]).length,nonnegatives:(seed.nonnegatives||[]).length,descendants:(seed.descendants||[]).length,introductions:(seed.introductions||[]).length});
    await loadState();
    if(!silent){render();toast(`Historique restauré : ${state.herds.length} éleveurs, ${state.campaigns.length} campagnes`)}
  }catch(e){console.error(e);if(!silent)toast('Historique : '+e.message);else throw e}
}

async function importBundledHistory(opts={}){const silent=!!opts.silent;try{if(!silent)toast('Chargement de l’historique fourni…');const r=await fetch('./migration/Suivi_Paratuberculose_32_65_V9_1_final_sans_analyses.xlsx');if(!r.ok)throw new Error('Fichier historique introuvable');const blob=await r.blob();const f=new File([blob],'historique_V9_1.xlsx',{type:blob.type||'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});await importExcel(f);if(!state.meta.campaignUserSet){await setMeta('currentCampaign','2025/2026')}await setMeta('bundledHistoryLoaded',APP_VERSION);await loadState();if(!silent)render();if(!silent)toast('Historique chargé')}catch(e){console.error(e);if(!silent)toast('Historique : '+e.message);else throw e}}
async function handleImport(type,file){if(!ensureWrite())return;try{toast(`Import de ${file.name}…`);if(type==='migration')await importExcel(file);else if(type.startsWith('animals'))await importAnimals(file,type.endsWith('32')?32:65);else await importAnalysis(file,type.endsWith('32')?32:65);await loadState();render();toast('Import terminé')}catch(e){console.error(e);toast('Erreur import : '+e.message)}}
function readFile(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsArrayBuffer(file)})}
function sheetObjects(wb,name){const sh=wb.Sheets[name];if(!sh)return[];return XLSX.utils.sheet_to_json(sh,{defval:'',raw:false,dateNF:'dd/mm/yyyy'})}
function pick(o,...keys){for(const k of keys){const found=Object.keys(o).find(x=>norm(x)===norm(k));if(found!==undefined&&o[found]!==''&&o[found]!=null)return o[found]}return''}
function parseFrenchDate(v){if(!v)return'';if(v instanceof Date)return v.toISOString();const m=String(v).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);return m?new Date(+m[3],+m[2]-1,+m[1]).toISOString():v}
async function importExcel(file){if(!window.XLSX)throw new Error('Bibliothèque Excel indisponible : connexion internet nécessaire au premier import.');const data=await readFile(file),w=XLSX.read(data,{type:'array',cellDates:true});
  const herds=sheetObjects(w,'CHEPTELS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE','N° cheptel / EDE'));return{id:ede||`herd${i}`,ede,dept:Number(pick(r,'Dépt','Département'))||Number(ede.slice(0,2)),name:pick(r,'Nom','Éleveur'),commune:pick(r,'Commune'),mode:pick(r,'Mode suivi','Mode de suivi'),protocol:pick(r,'Protocole'),vet:pick(r,'Vétérinaire'),currentQualification:pick(r,'Qualif AGDS actuelle','Qualification actuelle','Qualif après campagne','Situation garantie','Qualification AGDS'),qualificationAgds:pick(r,'Qualif AGDS actuelle','Qualification AGDS'),qualificationNational:pick(r,'Qualif logiciel national actuelle','Qualification logiciel national'),raw:r}}).filter(x=>x.ede);
  const campaigns=sheetObjects(w,'CAMPAGNES').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE'));const camp=pick(r,'Campagne');return{id:key(camp,ede,i),campaign:camp,ede,dept:Number(pick(r,'Dépt')),name:pick(r,'Nom'),mode:pick(r,'Mode suivi'),situation:pick(r,'Situation garantie'),protocol:pick(r,'Protocole'),protocolYear:pick(r,'Année protocole / ancienneté'),screeningPlanned:pick(r,'Dépistage prévu'),method:pick(r,'Méthode'),tested:num(pick(r,'Nb dépistés')),negative:num(pick(r,'Nb négatifs')),positive:num(pick(r,'Nb positifs')),status:pick(r,'Qualif / statut campagne'),campaignDate:parseFrenchDate(pick(r,'Date campagne')),comment:pick(r,'Commentaires / source'),raw:r}}).filter(x=>x.ede&&x.campaign);
  const nns=sheetObjects(w,'NON_NEGATIFS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE')),animalId=digits(pick(r,'N° bovin','Animal','Identifiant bovin'));const camp=pick(r,'Campagne');return{id:key(camp,ede,animalId,i),campaign:camp,dept:Number(pick(r,'Dépt')),ede,animalId,result:pick(r,'Résultat initial','Résultat'),date:parseFrenchDate(pick(r,'Date notification / recontrôle','Date','Date résultat')),presence:pick(r,'Présence actuelle','Présent / sorti','Présence'),exitDate:parseFrenchDate(pick(r,'Date sortie')),exitCause:pick(r,'Cause sortie'),motherKnownNonNegative:pick(r,'Mère connue non négative ?','Mère connue positive ?'),motherKnownPositive:pick(r,'Mère connue positive ?'),comment:pick(r,'Commentaires','Commentaire'),raw:r}}).filter(x=>x.ede&&x.animalId);
  const desc=sheetObjects(w,'DESCENDANTS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE')),animalId=digits(pick(r,'N° descendant','N° bovin','Animal'));return{id:key(ede,animalId,i),dept:Number(pick(r,'Dépt')),ede,motherId:digits(pick(r,'N° mère positive','N° mère')),animalId,birthDate:parseFrenchDate(pick(r,'Date naissance')),presence:pick(r,'Présence actuelle','Présent / sorti','Présence'),exitDate:parseFrenchDate(pick(r,'Date sortie')),exitCause:pick(r,'Cause sortie'),comment:pick(r,'Commentaires','Commentaire'),raw:r}}).filter(x=>x.ede&&x.animalId);
  const intro=sheetObjects(w,'INTRODUCTIONS').map((r,i)=>{const ede=digits(pick(r,'N° cheptel','N° EDE')),animalId=digits(pick(r,'N° bovin','Animal'));return{id:key(ede,animalId,i),dept:Number(pick(r,'Dépt')),ede,animalId,entryDate:parseFrenchDate(pick(r,'Date introduction','Date entrée')),origin:pick(r,'Provenance','Cheptel provenance'),control:pick(r,'Contrôle','Analyse','PCR intro','Sérologie intro'),result:pick(r,'Résultat','PCR intro','Sérologie intro'),comment:pick(r,'Commentaires','Commentaire'),raw:r}}).filter(x=>x.ede||x.animalId);
  const animals=[32,65].flatMap(dept=>sheetObjects(w,`ANIMAUX_${dept}_IMPORT`).map((r,i)=>{const animalId=digits(pick(r,'ID bovin normalisé','Identifiant bovin','N° bovin'));if(!animalId)return null;const exitDate=parseFrenchDate(pick(r,'Date sortie'));return{id:key(dept,animalId),dept,animalId,motherId:digits(pick(r,'ID mère normalisé','Numéro mère','N° mère')),ede:digits(pick(r,'N° EDE','Exploitation')),birthDate:parseFrenchDate(pick(r,'Date naissance')),exitDate,presence:pick(r,'Présence')||(exitDate?'Sorti':'Présent'),exitCause:pick(r,'Cause sortie','Cause de sortie'),workNo:pick(r,'N° travail','Numéro travail'),name:pick(r,'Nom'),sex:pick(r,'Sexe'),raw:r}}).filter(Boolean));
  for(const [s,arr] of [['herds',herds],['campaigns',campaigns],['nonnegatives',nns],['descendants',desc],['introductions',intro],['animals',animals]]){await db.clear(s);await db.bulkPut(s,arr)}
  const camp=pick(sheetObjects(w,'PARAMETRES')[1]||{},'Valeur')||currentCampaignDefault(); if(/^\d{4}\/\d{4}$/.test(camp))await setMeta('currentCampaign',camp);
}
function parseDelimited(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return[];const sep=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';const parseLine=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(ch===sep&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out.map(v=>v.replace(/^="(.*)"$/,'$1').trim())};const headers=parseLine(lines[0]);return lines.slice(1).map(l=>{const a=parseLine(l),o={};headers.forEach((h,i)=>o[h]=a[i]??'');return o})}
async function importAnimals(file,dept){const text=await file.text(),rows=parseDelimited(text);const arr=rows.map((r,i)=>{const animalId=digits(pick(r,'Identifiant bovin'));if(!animalId)return null;const exitDate=parseFrenchDate(pick(r,'Date sortie'));const code=pick(r,'Cause de sortie');const cm={E:'Élevage',B:'Boucherie',M:'Mort',H:'Héritage',C:'Autoconsommation'};return{id:key(dept,animalId),dept,animalId,motherId:digits(pick(r,'Numéro mère')),ede:digits(pick(r,'Exploitation')),birthDate:parseFrenchDate(pick(r,'Date naissance')),exitDate,presence:exitDate?'Sorti':'Présent',exitCause:cm[code]||code,workNo:pick(r,'Numéro travail'),name:pick(r,'Nom'),sex:pick(r,'Sexe'),raw:r}}).filter(Boolean);const old=state.animals.filter(a=>Number(a.dept)!==dept);await db.clear('animals');await db.bulkPut('animals',[...old,...arr])}
async function importAnalysis(file,dept){const text=await file.text(),rows=parseDelimited(text);const arr=rows.map((r,i)=>{if(pick(r,'Code maladie')!=='PTB'||pick(r,"Base de l'analyse")!=='S'||pick(r,"Type d'analyse")!=='I'||pick(r,'Contexte')!=='P')return null;const ede=digits(pick(r,"N° d'exploitation")),sampleDate=parseFrenchDate(pick(r,'Date de prélèvement')),camp=campaignFromDate(sampleDate);if(!ede||!camp)return null;return{id:key(dept,ede,camp,pick(r,"N° incrément du lot d'analyse")||i,pick(r,'Numéro du dossier laboratoire')),dept,ede,campaign:camp,sampleDate,tested:num(pick(r,"Nombre d'analyse ou de prélèvements effectués")),positive:num(pick(r,"Nombre d'analyses positives")),animalsConcerned:num(pick(r,"Nombre d'animaux concernés par l'analyse")),lastUpdate:parseFrenchDate(pick(r,'Date de la dernière mise à jour')),labFile:pick(r,'Numéro du dossier laboratoire'),raw:r}}).filter(Boolean);const keep=state.analysisLots.filter(x=>Number(x.dept)!==dept||!arr.some(n=>n.campaign===x.campaign));await db.clear('analysisLots');await db.bulkPut('analysisLots',[...keep,...arr])}

function runExport(type){let rows=[],headers=[];const herdRows=state.herds.map(h=>({Département:h.dept,EDE:h.ede,Nom:h.name,Commune:h.commune,Mode:h.mode,Qualification:h.currentQualification,Vétérinaire:h.vet}));if(type==='engages'){rows=herdRows;headers=Object.keys(rows[0]||{})}else if(type.startsWith('garantie')||type.startsWith('ass')){const guarantee=type.startsWith('garantie'),dept=type.endsWith('32')?32:type.endsWith('65')?65:null;rows=herdRows.filter((r,i)=>{const h=state.herds[i];return norm(h.mode).includes(guarantee?'garantie':'assain')&&(!dept||Number(h.dept)===dept)});headers=Object.keys(herdRows[0]||{})}else if(type==='bilan'){rows=[balance()];headers=Object.keys(rows[0])}else if(type==='positifs'){rows=[...analysisAggregate().values()].filter(a=>a.positive>0).map(a=>({EDE:a.ede,Nom:herdByEde(a.ede)?.name||'',Dépistés:a.tested,Négatifs:a.negative,Positifs:a.positive,Date:fmtDate(a.last),Statut:a.status}));headers=Object.keys(rows[0]||{EDE:'',Nom:'',Dépistés:'',Négatifs:'',Positifs:'',Date:'',Statut:''})}else if(type==='nonnegpresent'){const ai=animalIndex();rows=state.nonnegatives.filter(n=>(ai.get(String(n.animalId))?.presence||n.presence)==='Présent').map(n=>({...n,animalName:ai.get(String(n.animalId))?.name||''}));headers=['campaign','dept','ede','animalId','animalName','result','date','comment']}else if(type==='descendants'){rows=state.descendants;headers=['dept','ede','motherId','animalId','birthDate','presence','exitDate','exitCause','comment']}else if(type==='introductions'){rows=state.introductions;headers=['dept','ede','animalId','entryDate','origin','control','result','comment']}else if(type==='animalsAll'||type==='animalsPresent'){const engaged=new Set(state.herds.map(h=>String(h.ede)));rows=state.animals.filter(a=>engaged.has(String(a.ede))&&(type==='animalsAll'||a.presence==='Présent')).map(a=>({Département:a.dept,EDE:a.ede,'N° bovin':a.animalId,'N° travail':a.workNo,Nom:a.name,Sexe:a.sex,'Date naissance':fmtDate(a.birthDate),Présence:a.presence,'Date sortie':fmtDate(a.exitDate),'Cause sortie':a.exitCause,'N° mère':a.motherId}));headers=Object.keys(rows[0]||{'Département':'','EDE':'','N° bovin':''})}else if(type==='campaignFollowup'){const ag=analysisAggregate();rows=state.campaigns.filter(c=>c.campaign===state.campaign).map(c=>{const h=herdByEde(c.ede),a=ag.get(String(c.ede)),p=managementProposal(c.ede,a);return{EDE:c.ede,Nom:h?.name||c.name,Mode:h?.mode||c.mode,'Résultat reçu':a?'Oui':'Non','Dépistés':a?.tested||'',Positifs:a?.positive||'',Statut:a?.status||'En attente','Qualification proposée':p.qualification,'N+1 proposé':p.nextScreening,'Cas référentiel':p.caseRef}});headers=Object.keys(rows[0]||{EDE:'',Nom:''})};download(`PTB_${type}_${state.campaign.replace('/','-')}.csv`,toCSV(rows,headers),'text/csv;charset=utf-8')}

async function makeBackup(){const obj={version:APP_VERSION,createdAt:new Date().toISOString(),meta:state.meta};for(const s of STORES.filter(x=>x!=='meta'))obj[s]=await db.all(s);download(`PTB_GDS_backup_${today()}.json`,JSON.stringify(obj,null,2),'application/json')}
async function restoreBackup(file){if(!file)return;const obj=JSON.parse(await file.text());for(const s of STORES.filter(x=>x!=='meta')){await db.clear(s);if(Array.isArray(obj[s]))await db.bulkPut(s,obj[s])}if(obj.meta)for(const [k,v] of Object.entries(obj.meta))await setMeta(k,v);await loadState();render();toast('Sauvegarde restaurée')}
async function resetDb(){if(!confirm('Effacer toutes les données locales de l’application ?'))return;for(const s of STORES)await db.clear(s);await loadState();render()}

async function supabaseRequest(path,opts={}){const url=state.meta.supabaseUrl,keyv=state.meta.supabaseKey;if(!url||!keyv)throw new Error('Supabase non configuré');const token=state.auth.accessToken||keyv;const r=await fetch(url+'/rest/v1/'+path,{...opts,headers:{apikey:keyv,Authorization:'Bearer '+token,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal',...(opts.headers||{})}});if(!r.ok)throw new Error(await r.text());return r.status===204?null:r.json()}
async function authRequest(path,body){const url=state.meta.supabaseUrl,keyv=state.meta.supabaseKey;if(!url||!keyv)throw new Error('Supabase non configuré');const r=await fetch(url+'/auth/v1/'+path,{method:'POST',headers:{apikey:keyv,'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error_description||data.msg||data.message||'Erreur authentification');return data}
async function loadProfile(){if(!cloudLoggedIn())return null;const rows=await supabaseRequest(`ptb_user_profiles?select=id,email,role,active&id=eq.${encodeURIComponent(state.auth.user.id)}`,{method:'GET'});state.auth.profile=rows?.[0]||{id:state.auth.user.id,email:state.auth.user.email,role:'read',active:true};return state.auth.profile}
function saveAuthLocal(){localStorage.setItem('ptb_auth',JSON.stringify({accessToken:state.auth.accessToken,refreshToken:state.auth.refreshToken,user:state.auth.user}))}
async function loginSupabase(){try{await setMeta('supabaseUrl',$('#sbUrl').value.trim().replace(/\/$/,''));await setMeta('supabaseKey',$('#sbKey').value.trim());const email=$('#sbEmail').value.trim(),password=$('#sbPassword').value;if(!email||!password)return toast('E-mail et mot de passe obligatoires');const d=await authRequest('token?grant_type=password',{email,password});state.auth.accessToken=d.access_token;state.auth.refreshToken=d.refresh_token;state.auth.user=d.user;saveAuthLocal();await loadProfile();if(state.auth.profile?.active===false)throw new Error('Compte désactivé');await pullSupabase();render();toast('Connexion réussie')}catch(e){console.error(e);toast('Connexion : '+e.message)}}
async function logoutSupabase(){state.auth={accessToken:'',refreshToken:'',user:null,profile:null};localStorage.removeItem('ptb_auth');render();toast('Déconnecté')}
async function restoreAuth(){try{const x=JSON.parse(localStorage.getItem('ptb_auth')||'null');if(!x?.accessToken)return;state.auth={...state.auth,...x};await loadProfile()}catch(e){console.warn('Session cloud non restaurée',e);localStorage.removeItem('ptb_auth');state.auth={accessToken:'',refreshToken:'',user:null,profile:null}}}
async function pushSupabase(){try{if(!cloudLoggedIn())throw new Error('Connecte-toi d’abord');if(!canWrite())throw new Error('Compte en lecture seule');const records=[];for(const s of STORES.filter(x=>x!=='meta'))for(const o of await db.all(s))records.push({dataset:s,id:o.id,payload:o,updated_at:new Date().toISOString()});for(let i=0;i<records.length;i+=500)await supabaseRequest('ptb_records?on_conflict=dataset,id',{method:'POST',body:JSON.stringify(records.slice(i,i+500))});for(const [k,v] of Object.entries(state.meta))if(!['supabaseKey'].includes(k))await supabaseRequest('ptb_records?on_conflict=dataset,id',{method:'POST',body:JSON.stringify([{dataset:'meta',id:k,payload:{id:k,value:v},updated_at:new Date().toISOString()}])});toast('Base envoyée dans Supabase')}catch(e){console.error(e);toast('Supabase : '+e.message)}}
async function pullSupabase(){try{if(!cloudLoggedIn())throw new Error('Connecte-toi d’abord');const rows=await supabaseRequest('ptb_records?select=dataset,id,payload',{method:'GET'});if(!rows?.length){toast('Base cloud vide : aucune donnée remplacée');return}for(const s of STORES)if(s!=='meta')await db.clear(s);for(const r of rows){const target=r.dataset==='meta'?'meta':r.dataset;if(STORES.includes(target)){if(target==='meta'&&r.payload?.id==='supabaseKey')continue;await db.put(target,r.payload)}}await loadState();render();toast('Données cloud récupérées')}catch(e){console.error(e);toast('Supabase : '+e.message)}}
async function loadCloudUsers(){try{const rows=await supabaseRequest('ptb_user_profiles?select=id,email,role,active&order=email.asc',{method:'GET'});const box=$('#cloudUsers');if(!box)return;box.innerHTML=`<div class="table-wrap"><table><thead><tr><th>E-mail</th><th>Rôle</th><th>Actif</th></tr></thead><tbody>${rows.map(u=>`<tr><td>${esc(u.email||u.id)}</td><td><select class="cloud-role" data-uid="${esc(u.id)}"><option value="read" ${u.role==='read'?'selected':''}>Lecture</option><option value="write" ${u.role==='write'?'selected':''}>Écriture</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option></select></td><td><input class="cloud-active" data-uid="${esc(u.id)}" type="checkbox" ${u.active!==false?'checked':''}></td></tr>`).join('')}</tbody></table></div>`;$$('.cloud-role',box).forEach(el=>el.onchange=()=>updateCloudUser(el.dataset.uid,{role:el.value}));$$('.cloud-active',box).forEach(el=>el.onchange=()=>updateCloudUser(el.dataset.uid,{active:el.checked}))}catch(e){const box=$('#cloudUsers');if(box)box.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function updateCloudUser(id,patch){if(!isAdmin())return;try{await supabaseRequest(`ptb_user_profiles?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(patch)});toast('Droits mis à jour')}catch(e){toast('Droits : '+e.message)}}

let deferredInstallPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{
  e.preventDefault();
  deferredInstallPrompt=e;
  const b=document.getElementById('btnInstall');
  if(b){b.textContent='Installer l’appli';b.disabled=false;}
});
window.addEventListener('appinstalled',()=>{
  deferredInstallPrompt=null;
  const b=document.getElementById('btnInstall');
  if(b){b.textContent='Appli installée';b.disabled=true;}
});
function isStandaloneMode(){
  return window.matchMedia?.('(display-mode: standalone)').matches || window.navigator.standalone===true;
}
async function installApp(){
  if(isStandaloneMode()){
    toast('L’application est déjà installée sur cet appareil.');
    return;
  }
  if(deferredInstallPrompt){
    const p=deferredInstallPrompt;
    deferredInstallPrompt=null;
    await p.prompt();
    try{await p.userChoice}catch(e){}
    return;
  }
  const ua=navigator.userAgent||'';
  if(/iphone|ipad|ipod/i.test(ua)) toast('Sur iPhone/iPad : Partager → Sur l’écran d’accueil.');
  else if(/android/i.test(ua)) toast('Dans Chrome : menu ⋮ → Installer l’application / Ajouter à l’écran d’accueil.');
  else toast('Dans Chrome/Edge : utilise l’icône d’installation dans la barre d’adresse ou le menu ⋮ → Installer Paratuberculose GDS 32-65.');
}

async function init(){await db.open();await loadState();await restoreAuth();if(!state.meta.campaignUserSet&&state.campaign!=='2025/2026'){state.campaign='2025/2026';await setMeta('currentCampaign',state.campaign)}if(state.meta.bundledHistoryLoaded!=='1.2.4'||state.herds.length<190||state.campaigns.length<1900){try{await restoreBundledHistory({silent:true});await loadState()}catch(e){console.warn('Historique initial non chargé automatiquement',e)}}populateCampaignSelector();$('#globalCampaign').onchange=async e=>{state.campaign=e.target.value;await setMeta('currentCampaign',state.campaign);await setMeta('campaignUserSet',true);render()};$('#btnBackup').onclick=makeBackup;const installBtn=$('#btnInstall');if(installBtn){installBtn.onclick=installApp;if(isStandaloneMode()){installBtn.textContent='Appli installée';installBtn.disabled=true;}}$$('.nav-btn').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});}render()}
init().catch(e=>{$('#app').innerHTML=`<div class="error">Erreur au démarrage : ${esc(e.message)}</div>`;console.error(e)});
